('infinix-xbuds-3', 'Infinix XBuds 3 True Wireless Earbuds', 'audio', 22000, 22000, 17800, 70, 0.046, '/assets/products/infinix-xbuds-3.jpg', 'Infinix XBuds 3 feature 12mm dynamic drivers with Bass Boost, Bluetooth 5.3, ANC up to 30dB, and 35-hour total battery life (7 hours earbuds + 28 hours case). Dual-mic ENC for calls, 60ms low-latency gaming mode, IPX5 water resistance, and Google Fast Pair. The compact case supports wireless charging.', 1, unixepoch(), 1, 17800, '/assets/products/infinix-xbuds-3.jpg', 19580, 4.5, 0, 'Infinix', 0, 1),

('infinix-xbuds-neo', 'Infinix XBuds Neo True Wireless Earbuds', 'audio', 12000, 12000, 9500, 90, 0.043, '/assets/products/infinix-xbuds-neo.jpg', 'Infinix XBuds Neo offer 10mm drivers, Bluetooth 5.2, 28-hour total battery, IPX4 rating, and touch controls. Low-latency mode for gaming, USB-C charging, and instant pairing with Infinix/HiOs phones. Affordable wireless freedom.', 1, unixepoch(), 1, 9500, '/assets/products/infinix-xbuds-neo.jpg', 10450, 4.3, 0, 'Infinix', 0, 0),

